#include "net.h"
#include "rtl8139.h"
#include "lib.h"

static u8 mac[6],ip[4]={0,0,0,0},gw[4]={0,0,0,0},dns[4]={0,0,0,0},mask[4]={255,255,255,0};
static u8 arp_ip[4],arp_mac[6];static int arp_valid=0;static u8 pending_ping[4];static int ping_pending=0;
static u32 rxn=0,txn=0,pings=0,ipid=1;static int ready=0;static char statebuf[32]="NO DRIVER";static u32 xid=0x50434F53u;static u8 offer_ip[4],server_ip[4];
static u8 frame[1600];
static u32 be32(u32 v){return ((v&0xff)<<24)|((v&0xff00)<<8)|((v>>8)&0xff00)|((v>>24)&0xff);}static int ip_eq(const u8*a,const u8*b){for(int i=0;i<4;i++)if(a[i]!=b[i])return 0;return 1;}static void ip_copy(u8*d,const u8*s){for(int i=0;i<4;i++)d[i]=s[i];}
static u16 csum(const u8*d,u32 n){u32 s=0;while(n>1){s+=((u16)d[0]<<8)|d[1];d+=2;n-=2;}if(n)s+=(u16)d[0]<<8;while(s>>16)s=(s&0xffff)+(s>>16);return (u16)~s;}
static void ipstr(const u8*a,char*out){out[0]=0;for(int i=0;i<4;i++){char n[12];kitoa(a[i],n);kstrcat(out,n,16);if(i!=3)kstrcat(out,".",16);}}
static void send_eth(const u8*dst,u16 type,const u8*payload,u32 len){if(len+14>sizeof(frame))return;for(int i=0;i<6;i++){frame[i]=dst[i];frame[6+i]=mac[i];}frame[12]=(u8)(type>>8);frame[13]=(u8)type;kmemcpy(frame+14,payload,len);if(rtl8139_send(frame,len+14))txn++;}
static void arp_request(const u8*target){u8 p[28];kmemset(p,0,sizeof(p));p[0]=0;p[1]=1;p[2]=0x08;p[3]=0;p[4]=6;p[5]=4;p[6]=0;p[7]=1;kmemcpy(p+8,mac,6);kmemcpy(p+14,ip,4);kmemcpy(p+24,target,4);u8 b[6]={255,255,255,255,255,255};send_eth(b,0x0806,p,28);}
static void arp_reply(const u8*dstmac,const u8*dstip){u8 p[28];kmemset(p,0,sizeof(p));p[0]=0;p[1]=1;p[2]=0x08;p[3]=0;p[4]=6;p[5]=4;p[6]=0;p[7]=2;kmemcpy(p+8,mac,6);kmemcpy(p+14,ip,4);kmemcpy(p+18,dstmac,6);kmemcpy(p+24,dstip,4);send_eth(dstmac,0x0806,p,28);}
static void send_ipv4(const u8*dstip,const u8*dstmac,u8 proto,const u8*payload,u16 plen,const u8*src_override){u8 p[1540];u16 total=(u16)(20+plen);kmemset(p,0,total);p[0]=0x45;p[2]=(u8)(total>>8);p[3]=(u8)total;u16 id=(u16)ipid++;p[4]=(u8)(id>>8);p[5]=(u8)id;p[6]=0x40;p[8]=64;p[9]=proto;const u8*src=src_override?src_override:ip;kmemcpy(p+12,src,4);kmemcpy(p+16,dstip,4);u16 sum=csum(p,20);p[10]=(u8)(sum>>8);p[11]=(u8)sum;kmemcpy(p+20,payload,plen);send_eth(dstmac,0x0800,p,total);}
static void send_icmp(const u8*dst,const u8*dmac){u8 p[32];kmemset(p,0,sizeof(p));p[0]=8;p[4]=0x50;p[5]=0x43;p[6]=0;p[7]=1;const char*s="PCOS-PING";for(int i=0;s[i]&&8+i<(int)sizeof(p);i++)p[8+i]=(u8)s[i];u16 sum=csum(p,sizeof(p));p[2]=(u8)(sum>>8);p[3]=(u8)sum;send_ipv4(dst,dmac,1,p,sizeof(p),0);}
static void send_udp_broadcast(const u8*data,u16 len){u8 u[600];if((u32)len+8>sizeof(u))return;u16 total=(u16)(len+8);u[0]=0;u[1]=68;u[2]=0;u[3]=67;u[4]=(u8)(total>>8);u[5]=(u8)total;u[6]=u[7]=0;kmemcpy(u+8,data,len);u8 dip[4]={255,255,255,255},dmac[6]={255,255,255,255,255,255},zero[4]={0,0,0,0};send_ipv4(dip,dmac,17,u,total,zero);}
static u32 dhcp_base(u8*b,u8 msg){kmemset(b,0,400);b[0]=1;b[1]=1;b[2]=6;u32 x=be32(xid);kmemcpy(b+4,&x,4);b[10]=0x80;kmemcpy(b+28,mac,6);b[236]=99;b[237]=130;b[238]=83;b[239]=99;u32 p=240;b[p++]=53;b[p++]=1;b[p++]=msg;return p;}
static void dhcp_discover(void){u8 b[400];u32 p=dhcp_base(b,1);b[p++]=55;b[p++]=3;b[p++]=1;b[p++]=3;b[p++]=6;b[p++]=255;send_udp_broadcast(b,(u16)p);kstrncpy(statebuf,"DHCP DISCOVER",sizeof(statebuf));}
static void dhcp_request(void){u8 b[400];u32 p=dhcp_base(b,3);b[p++]=50;b[p++]=4;kmemcpy(b+p,offer_ip,4);p+=4;b[p++]=54;b[p++]=4;kmemcpy(b+p,server_ip,4);p+=4;b[p++]=55;b[p++]=3;b[p++]=1;b[p++]=3;b[p++]=6;b[p++]=255;send_udp_broadcast(b,(u16)p);kstrncpy(statebuf,"DHCP REQUEST",sizeof(statebuf));}
static void dhcp_parse(const u8*b,u32 n){if(n<240||b[0]!=2)return;u32 xx;kmemcpy(&xx,b+4,4);if(be32(xx)!=xid)return;u8 msg=0,sm[4]={255,255,255,0},rgw[4]={0,0,0,0},rdns[4]={0,0,0,0},srv[4]={0,0,0,0};for(u32 p=240;p<n;){u8 o=b[p++];if(o==0)continue;if(o==255)break;if(p>=n)break;u8 l=b[p++];if(p+l>n)break;if(o==53&&l>=1)msg=b[p];else if(o==1&&l>=4)kmemcpy(sm,b+p,4);else if(o==3&&l>=4)kmemcpy(rgw,b+p,4);else if(o==6&&l>=4)kmemcpy(rdns,b+p,4);else if(o==54&&l>=4)kmemcpy(srv,b+p,4);p+=l;}if(msg==2){kmemcpy(offer_ip,b+16,4);ip_copy(server_ip,srv);dhcp_request();}else if(msg==5){kmemcpy(ip,b+16,4);ip_copy(mask,sm);ip_copy(gw,rgw);ip_copy(dns,rdns);kstrncpy(statebuf,"DHCP BOUND",sizeof(statebuf));arp_valid=0;}}
static void handle_arp(const u8*p,u32 n){if(n<28||p[0]!=0||p[1]!=1||p[2]!=0x08||p[3]!=0||p[4]!=6||p[5]!=4)return;u16 op=(u16)((p[6]<<8)|p[7]);const u8*sm=p+8;const u8*sip=p+14;const u8*tip=p+24;if(op==1&&ip_eq(tip,ip))arp_reply(sm,sip);if(op==2){ip_copy(arp_ip,sip);kmemcpy(arp_mac,sm,6);arp_valid=1;if(ping_pending&&ip_eq(arp_ip,pending_ping)){send_icmp(pending_ping,arp_mac);ping_pending=0;}}}
static void handle_ip(const u8*p,u32 n){if(n<20||(p[0]>>4)!=4)return;u32 ih=(p[0]&15)*4u;if(ih<20||ih>n)return;u16 total=(u16)((p[2]<<8)|p[3]);if(total>n)total=(u16)n;u8 proto=p[9];const u8*src=p+12;const u8*dst=p+16;if(proto==1&&total>=ih+8){const u8*i=p+ih;if(i[0]==0){pings++;ip_copy(arp_ip,src);for(int k=0;k<6;k++)arp_mac[k]=frame[6+k];arp_valid=1;}else if(i[0]==8&&ip_eq(dst,ip)){u8 q[1500];u32 l=total-ih;if(l>sizeof(q))l=sizeof(q);kmemcpy(q,i,l);q[0]=0;q[2]=q[3]=0;u16 s=csum(q,l);q[2]=(u8)(s>>8);q[3]=(u8)s;u8 smac[6];kmemcpy(smac,frame+6,6);send_ipv4(src,smac,1,q,(u16)l,0);}}
 else if(proto==17&&total>=ih+8){const u8*u=p+ih;u16 sp=(u16)((u[0]<<8)|u[1]),dp=(u16)((u[2]<<8)|u[3]),ul=(u16)((u[4]<<8)|u[5]);if(sp==67&&dp==68&&ul>=8&&ih+ul<=total)dhcp_parse(u+8,ul-8);}}
void net_init(void){ready=rtl8139_init();if(!ready){kstrncpy(statebuf,"NO RTL8139",sizeof(statebuf));return;}rtl8139_mac(mac);kstrncpy(statebuf,"LINK UP",sizeof(statebuf));net_request_dhcp();}
void net_poll(void){if(!ready)return;for(int z=0;z<8;z++){int n=rtl8139_recv(frame,sizeof(frame));if(n<=0)break;rxn++;if(n<14)continue;u16 t=(u16)((frame[12]<<8)|frame[13]);if(t==0x0806)handle_arp(frame+14,(u32)n-14);else if(t==0x0800)handle_ip(frame+14,(u32)n-14);}}
int net_ready(void){return ready;}const char*net_driver(void){return ready?"RTL8139":"NONE";}void net_get_mac(char out[18]){static const char h[]="0123456789ABCDEF";int p=0;for(int i=0;i<6;i++){out[p++]=h[mac[i]>>4];out[p++]=h[mac[i]&15];if(i!=5)out[p++]=':';}out[p]=0;}void net_get_ip(char o[16]){ipstr(ip,o);}void net_get_gateway(char o[16]){ipstr(gw,o);}void net_get_dns(char o[16]){ipstr(dns,o);}void net_request_dhcp(void){if(ready)dhcp_discover();}void net_ping_gateway(void){if(!ready)return;u8 zero[4]={0,0,0,0};if(ip_eq(gw,zero))return;ip_copy(pending_ping,gw);if(arp_valid&&ip_eq(arp_ip,gw)){send_icmp(gw,arp_mac);ping_pending=0;}else{ping_pending=1;arp_request(gw);}}u32 net_rx_packets(void){return rxn;}u32 net_tx_packets(void){return txn;}u32 net_ping_replies(void){return pings;}const char *net_state(void){return statebuf;}
